  argv: string[],
  spec: T,
  stopAtPositional = true,
  permissive = false,
): Arg.Result<T> | Error {
  try {
    return Arg(spec, { argv, stopAtPositional, permissive })
  } catch (e: any) {
    return e
  }
}

