 */
export type EnvFileResult = {
  /** Whether the file was created (it did not exist before). */
  created: boolean
  /** Keys that were newly written to the file. */
  added: string[]
  /** Keys that already existed and were updated in-place. */
  updated: string[]
}

/**
 * Serializes a single environment variable line. Values are always wrapped in
 * single quotes to prevent variable expansion by shells and dotenv loaders.
 */
function formatLine(key: string, value: string): string {
  return `${key}='${value}'`
}

/**
 * Creates or updates a `.env` file with the given key-value pairs.
 *
 * - When the file does not exist it is created with all provided keys.
 * - Existing keys are updated in-place, new keys are appended.
 * - Values are written with single quotes to prevent variable expansion.
 */
export function upsertEnvFile(envPath: string, vars: Record<string, string>): EnvFileResult {
  const added: string[] = []
  const updated: string[] = []

  if (!fs.existsSync(envPath)) {
    const content = Object.entries(vars)
      .map(([key, value]) => `${formatLine(key, value)}\n`)
      .join('')
    fs.writeFileSync(envPath, content)
    return { created: true, added: Object.keys(vars), updated: [] }
  }

  let content = fs.readFileSync(envPath, 'utf8')

  for (const [key, value] of Object.entries(vars)) {
    // Match an existing assignment for this key at the start of a line.
    const keyRegex = new RegExp(`^${key.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}=.*$`, 'm')
    if (keyRegex.test(content)) {
      content = content.replace(keyRegex, formatLine(key, value))
      updated.push(key)
    } else {
      if (content.length > 0 && !content.endsWith('\n')) {
        content += '\n'
      }
      content += `${formatLine(key, value)}\n`
      added.push(key)
    }
  }

  fs.writeFileSync(envPath, content)
  return { created: false, added, updated }
}

/**
 * Checks whether a `.gitignore` file exists in the given directory and whether
 * it contains an entry for `.env`.
 */
export function checkGitignore(dir: string): 'no-file' | 'ok' | 'missing-entry' {
  const gitignorePath = path.join(dir, '.gitignore')
  if (!fs.existsSync(gitignorePath)) {
    return 'no-file'
  }

  const lines = fs
    .readFileSync(gitignorePath, 'utf8')
    .split(/\r?\n/)
    .map((line) => line.trim())

  if (lines.some((line) => line === '.env' || line === '/.env')) {
    return 'ok'
  }

  return 'missing-entry'
}

/**
 * Writes the connection strings from the given {@link ConnectionResult} to the
 * `.env` file in the specified directory.
 */
export function writeLocalFiles(dir: string, connection: ConnectionResult): { env: EnvFileResult } {
  const envPath = path.join(dir, '.env')
