 */
export type Project = operations['getV1Projects']['responses']['200']['content']['application/json']['data'][number]

/**
 * A single database as returned by the Management API.
 */
export type Database =
  operations['getV1ProjectsByProjectIdDatabases']['responses']['200']['content']['application/json']['data'][number]

/**
 * Result returned by {@link createDevConnection}.
 */
export type ConnectionResult = {
  connectionString: string
}

/**
 * Extracts the error code from a Management API error payload, tolerating both
 * the nested (`{ error: { code } }`) and flat (`{ code }`) shapes.
 */
function getApiErrorCode(error: unknown): string | undefined {
  const err = error as { code?: string; error?: { code?: string } } | undefined
  return err?.error?.code ?? err?.code
}

/**
 * Extracts a human-readable message from a Management API error payload.
 */
function getApiErrorMessage(error: unknown): string | undefined {
  const err = error as { message?: string; error?: { message?: string } } | undefined
  return err?.error?.message ?? err?.message
}

/**
 * Creates a dev connection for the given database and returns the preferred
 * connection string.
 *
 * The direct endpoint is preferred, falling back to the pooled endpoint, then
 * to the deprecated top-level `connectionString` field.
 */
export async function createDevConnection(client: ApiClient, databaseId: string): Promise<ConnectionResult> {
  const { data, error } = await client.POST('/v1/connections', {
    body: {
      databaseId,
      name: 'Prisma CLI',
    },
  })

  if (error) {
    const code = getApiErrorCode(error)
    if (code === 'authentication-failed') {
      throw new Error('Invalid credentials')
    }
    if (code === 'not_found') {
      throw new Error('Database not found')
    }
    throw new Error(getApiErrorMessage(error) ?? 'Failed to create connection')
  }

  const connection = (data as { data?: Record<string, any> } | undefined)?.data
  const connectionString: string | undefined =
    connection?.endpoints?.direct?.connectionString ??
    connection?.endpoints?.pooled?.connectionString ??
    connection?.connectionString

  if (!connectionString) {
    throw new Error('No connection string found in the API response')
  }

  return { connectionString }
}

/**
 * Returns the list of projects the authenticated actor has access to.
 */
export async function listProjects(client: ApiClient): Promise<Project[]> {
  const { data, error } = await client.GET('/v1/projects')
  if (error) {
    throw new Error(getApiErrorMessage(error) ?? 'Failed to list projects')
  }
  return data?.data ?? []
}

/**
 * Returns the list of databases for the given project.
 */
export async function listDatabases(client: ApiClient, projectId: string): Promise<Database[]> {
  const { data, error } = await client.GET('/v1/projects/{projectId}/databases', {
    params: { path: { projectId } },
  })
  if (error) {
    throw new Error(getApiErrorMessage(error) ?? 'Failed to list databases')
  }
  return data?.data ?? []
}

