  sanitizeErrorMessage,
} from './management-api'
import { checkGitignore, formatEnvSummary, isAlreadyLinked, writeLocalFiles } from './local-setup'

const DATABASE_ID_PREFIX = 'db_'

/**
 * `prisma postgres link`
 *
 * Links a local project to a hosted Prisma Postgres database by writing the
 * connection string to the local `.env` file.
 */
export class Link {
  static new(): Link {
    return new Link()
  }

  private constructor() {}

  private static help = format(`
    Link your local project to a Prisma Postgres database.

    ${bold('Usage')}

      ${dim('$')} prisma postgres link [options]

    ${bold('Options')}

           -h, --help   Display this help message
          --api-key     A Prisma Postgres API key to authenticate non-interactively
          --database    The id of the database to link (must start with '${DATABASE_ID_PREFIX}')
          --force       Re-link even if the project is already linked

    ${bold('Examples')}

      Link interactively (opens the browser to authenticate)
      ${dim('$')} prisma postgres link

      Link non-interactively with an API key
      ${dim('$')} prisma postgres link --api-key <key> --database db_xxx
  `)

  public help(error?: string): string | HelpError {
    if (error) {
      return new HelpError(`\n${bold(red(`!`))} ${error}\n${Link.help}`)
    }
    return Link.help
  }

  async parse(argv: string[], _config: unknown, cwd: string = process.cwd()): Promise<string | HelpError | Error> {
    const args = arg(argv, {
      '--help': Boolean,
      '-h': '--help',
      '--api-key': String,
      '--database': String,
      '--force': Boolean,
    })

    if (isError(args)) {
      return this.help(args.message)
    }

    if (args['--help']) {
      return this.help()
    }

    const apiKeyFlag = args['--api-key']
    const databaseFlag = args['--database']
    const force = Boolean(args['--force'])

    // Interactive mode is used only when neither credential-related flag is set.
    const interactive = !apiKeyFlag && !databaseFlag

    try {
      if (interactive) {
        return await this.linkInteractive({ cwd, force })
      }

      // Non-interactive mode requires a database to link to.
      if (!databaseFlag) {
        return this.help(`The --database flag is required when using --api-key.`)
      }

      const apiKey = apiKeyFlag ?? process.env.PRISMA_API_KEY
      if (!apiKey) {
        return this.help(`An API key is required. Provide --api-key or set the PRISMA_API_KEY environment variable.`)
      }

      if (!databaseFlag.startsWith(DATABASE_ID_PREFIX)) {
        return this.help(
          `Invalid --database value "${databaseFlag}". A database id must start with '${DATABASE_ID_PREFIX}'.`,
        )
      }

      return await this.linkNonInteractive({ cwd, apiKey, databaseId: databaseFlag, force })
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error)
      return this.help(sanitizeErrorMessage(message))
    }
  }

  private async linkNonInteractive(opts: {
    cwd: string
    apiKey: string
    databaseId: string
    force: boolean
  }): Promise<string | HelpError> {
    const { cwd, apiKey, databaseId, force } = opts

    const alreadyLinked = this.checkAlreadyLinked({ cwd, force })
    if (alreadyLinked) {
      return alreadyLinked
    }

    const client = createManagementApiClient({ token: apiKey })
    const connection = await createDevConnection(client, databaseId)

    return this.buildSuccessOutput({ cwd, connection })
  }

  private async linkInteractive(opts: { cwd: string; force: boolean }): Promise<string | HelpError> {
    const { cwd, force } = opts

    const alreadyLinked = this.checkAlreadyLinked({ cwd, force })
    if (alreadyLinked) {
      return alreadyLinked
    }

    const connection = await this.withBrowserAuth(async (client) => {
      const projects = await listProjects(client)
      if (projects.length === 0) {
        throw new NoProjectsError()
      }

      const projectId = await select({
        message: 'Select a project:',
        choices: projects.map((project) => ({
          name: project.name,
          value: project.id,
        })),
        loop: true,
      })

      const databases = await listDatabases(client, projectId)
      const readyDatabases = databases.filter((database) => database.status === 'ready')
      if (readyDatabases.length === 0) {
        throw new NoReadyDatabasesError()
      }

      const database = readyDatabases.length === 1 ? readyDatabases[0] : await this.selectDatabase(readyDatabases)

      return createDevConnection(client, database.id)
    })

    return this.buildSuccessOutput({ cwd, connection })
  }

  private async selectDatabase(databases: Database[]): Promise<Database> {
    const databaseId = await select({
      message: 'Select a database:',
      choices: databases.map((database) => ({
        name: database.name,
        value: database.id,
      })),
      loop: true,
    })

    return databases.find((database) => database.id === databaseId) ?? databases[0]
  }

  /**
   * Runs the given operation with a browser-authenticated Management API client.
   * If the stored refresh token is invalid, the user is prompted to log in again
   * and the operation is retried once.
   */
  private async withBrowserAuth<T>(fn: (client: ApiClient) => Promise<T>): Promise<T> {
    try {
      const managementAPI = createAuthenticatedManagementAPI()
      return await fn(managementAPI.client)
    } catch (error) {
      if (isRefreshTokenInvalid(error)) {
        await login({ utmMedium: 'command-postgres-link' })
        const managementAPI = createAuthenticatedManagementAPI()
        return await fn(managementAPI.client)
      }
      throw error
    }
  }

  private checkAlreadyLinked(opts: { cwd: string; force: boolean }): string | undefined {
    if (opts.force) {
      return undefined
    }
    if (isAlreadyLinked(opts.cwd)) {
      return `This project is already linked to a Prisma Postgres database.\nUse ${green('--force')} to re-link it to a different database.`
    }
    return undefined
  }

