describe('non-interactive', () => {
  it('creates connection, writes env, returns linked successfully; no models -> Define your data model', async () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(),'ni-'))
    createManagementApiClient.mockReturnValue(client())
    postSpy.mockResolvedValue({ data: { data: { endpoints: { direct: { connectionString: 'postgres://direct.example' } } } } })
    const res = await Link.new().parse(['--api-key','KEY','--database','db_abc'], {}, dir)
    expect(createManagementApiClient).toHaveBeenCalledWith({ token: 'KEY' })
    expect(typeof res).toBe('string')
    expect(res).toContain('linked successfully')
    expect(res).toContain('Define your data model')
    const env = fs.readFileSync(path.join(dir,'.env'),'utf8')
    expect(env).toBe("DATABASE_URL='postgres://direct.example'\n")
  })

  it('with models -> prisma generate & prisma migrate dev', async () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(),'ni2-'))
    fs.mkdirSync(path.join(dir,'prisma'))
    fs.writeFileSync(path.join(dir,'prisma','schema.prisma'), 'model User {\n id Int @id\n}\n')
    createManagementApiClient.mockReturnValue(client())
    postSpy.mockResolvedValue({ data: { data: { endpoints: { direct: { connectionString: 'postgres://d' } } } } })
    const res = await Link.new().parse(['--api-key','KEY','--database','db_abc'], {}, dir) as string
    expect(res).toContain('prisma generate')
    expect(res).toContain('prisma migrate dev')
  })

  it('uses PRISMA_API_KEY when --api-key omitted', async () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(),'ni3-'))
    process.env.PRISMA_API_KEY = 'ENVKEY'
    createManagementApiClient.mockReturnValue(client())
    postSpy.mockResolvedValue({ data: { data: { connectionString: 'postgres://d' } } })
    await Link.new().parse(['--database','db_abc'], {}, dir)
    expect(createManagementApiClient).toHaveBeenCalledWith({ token: 'ENVKEY' })
    delete process.env.PRISMA_API_KEY
  })

  it('unauthorized -> HelpError Invalid credentials', async () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(),'ni4-'))
    createManagementApiClient.mockReturnValue(client())
    postSpy.mockResolvedValue({ error: { error: { code: 'authentication-failed', message: 'no' } } })
    const res = await Link.new().parse(['--api-key','KEY','--database','db_abc'], {}, dir)
    expect(res).toBeInstanceOf(HelpError)
    expect((res as HelpError).message).toContain('Invalid credentials')
  })
})

